const form=document.querySelector('#sign-in-form'),status=document.querySelector('#sign-in-status'),button=form.querySelector('button');
form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;button.disabled=true;button.textContent='Signing in…';status.textContent='';try{const response=await fetch('/api/private?route=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.elements.email.value,password:form.elements.password.value})}),result=await response.json();form.elements.password.value='';if(!response.ok)throw new Error(result.error||'Sign-in could not complete.');location.replace('/');}catch(error){status.textContent=error.message||'Connection failed. Please retry.';status.tabIndex=-1;status.focus();}finally{button.disabled=false;button.textContent='Sign in';}});
